 examples=[("She said she was busy.", "Meşgul olduğunu söyledi."), ("He told me he would come.", "Geleceğini söyledi."), ("They asked where we lived.", "Nerede yaşadığımızı sordular.")],
 mistakes=[("He said me…", "He told me… / He said to me…", "say + kişi doğrudan gelmez."), ("She asked where did I live.", "She asked where I lived.", "Dolaylı soruda devrik yapı yok.")],
